$explorerBlock = @'
function explorerItemsFrom(response) {
  return Array.isArray(response)
    ? response
    : response?.entries || response?.items || response?.data || [];
}

function explorerEntry(item) {
  const name = String(item?.name || item?.path || item?.relativePath || '');
  const relativePath = String(item?.relativePath || item?.path || name);
  const directory =
    item?.type === 'directory'
    || item?.directory === true
    || item?.isDirectory === true;

  return { name, relativePath, directory };
}

async function refreshFiles() {
  try {
    const response = await api.list('.');
    explorerRootItems = explorerItemsFrom(response);
    expandedExplorerPaths.clear();
    explorerChildren.clear();
    renderFileItems();
  } catch (error) {
    recordUiProblem('workspace', error);
  }
}

function renderFileItems() {
  const host = $('fileList');
  if (!host) return;

  const query = $('fileSearch')?.value.trim().toLowerCase() || '';

  const renderLevel = (items, depth = 0) => items.map(rawItem => {
    const entry = explorerEntry(rawItem);
    const expanded =
      entry.directory
      && expandedExplorerPaths.has(entry.relativePath);

    const children = expanded
      ? (explorerChildren.get(entry.relativePath) || [])
      : [];

    const childrenMarkup = expanded
      ? renderLevel(children, depth + 1)
      : '';

    const selfMatches =
      !query
      || entry.name.toLowerCase().includes(query)
      || entry.relativePath.toLowerCase().includes(query);

    if (!selfMatches && !childrenMarkup) return '';

    const selected = selectedExplorerPath === entry.relativePath;
    const icon = entry.directory
      ? (expanded ? '▾' : '▸')
      : '·';

    return '<li class="file-row'
      + (selected ? ' is-selected' : '')
      + '" data-path="' + escapeHtml(entry.relativePath)
      + '" data-directory="' + entry.directory
      + '" data-depth="' + depth
      + '" tabindex="0"'
      + ' aria-selected="' + (selected ? 'true' : 'false')
      + '" style="padding-left:' + (9 + depth * 14) + 'px">'
      + '<span class="file-icon"'
      + (entry.directory ? ' data-explorer-toggle="true"' : '')
      + '>' + icon + '</span>'
      + '<span class="file-name">'
      + escapeHtml(entry.name)
      + '</span>'
      + '</li>'
      + childrenMarkup;
  }).join('');

  host.innerHTML =
    renderLevel(explorerRootItems)
    || '<li class="file-row muted-row">No matching files</li>';

  for (const row of host.querySelectorAll('[data-path]')) {
    row.addEventListener('click', event => {
      selectedExplorerPath = row.dataset.path;

      for (const candidate of host.querySelectorAll('[data-path]')) {
        const isSelected =
          candidate.dataset.path === selectedExplorerPath;

        candidate.classList.toggle('is-selected', isSelected);
        candidate.setAttribute(
          'aria-selected',
          isSelected ? 'true' : 'false'
        );
      }

      if (
        event.target.closest('[data-explorer-toggle]')
        && row.dataset.directory === 'true'
      ) {
        toggleExplorerDirectory(row.dataset.path);
      }
    });

    row.addEventListener('dblclick', event => {
      event.preventDefault();

      if (row.dataset.directory === 'true') {
        toggleExplorerDirectory(row.dataset.path);
      } else {
        openFile(row.dataset.path);
      }
    });

    row.addEventListener('keydown', event => {
      if (event.key === 'Enter') {
        event.preventDefault();

        if (row.dataset.directory === 'true') {
          toggleExplorerDirectory(row.dataset.path);
        } else {
          openFile(row.dataset.path);
        }

        return;
      }

      if (
        event.key === 'ArrowRight'
        && row.dataset.directory === 'true'
        && !expandedExplorerPaths.has(row.dataset.path)
      ) {
        event.preventDefault();
        toggleExplorerDirectory(row.dataset.path);
        return;
      }

      if (
        event.key === 'ArrowLeft'
        && row.dataset.directory === 'true'
        && expandedExplorerPaths.has(row.dataset.path)
      ) {
        event.preventDefault();
        toggleExplorerDirectory(row.dataset.path);
      }
    });
  }
}

async function toggleExplorerDirectory(relativePath) {
  if (!relativePath) return;

  if (expandedExplorerPaths.has(relativePath)) {
    expandedExplorerPaths.delete(relativePath);
    renderFileItems();
    return;
  }

  try {
    if (!explorerChildren.has(relativePath)) {
      const response = await api.list(relativePath);
      explorerChildren.set(
        relativePath,
        explorerItemsFrom(response)
      );
    }

    expandedExplorerPaths.add(relativePath);
    renderFileItems();
  } catch (error) {
    recordUiProblem('workspace', error);
  }
}

